    "55a697816bedf97c5fa3ef36a4d9d39d98f6f572d825a38541afe62e19203773";

#[derive(Debug, thiserror::Error)]
pub enum CognitiveStoreError {
    #[error("invalid cognitive record: {0}")]
    Invalid(String),
    #[error("cognitive scope denied: {0}")]
    AccessDenied(String),
    #[error("cognitive revision conflict: {0}")]
    Conflict(String),
    #[error("cognitive store is corrupt: {0}")]
    Corrupt(String),
    #[error("cognitive store is unavailable: {0}")]
    Unavailable(String),
}

#[derive(Clone)]
pub struct CognitiveStore {
    pub(crate) pool: SqlitePool,
    pub(crate) commit_gate: CognitiveCommitGate,
    pub(crate) owner_agent_id: AgentId,
    path: PathBuf,
    _open_guard: Option<Arc<CognitiveStoreOpenGuard>>,
}

#[derive(Debug)]
pub(crate) struct CognitiveStoreOpenGuard {
    custody: Arc<CognitiveStoreLockCustody>,
}

// Physical connections retain the original descriptors without retaining a
// public store handle. Reference counts are not proof of exclusive authority.
#[derive(Debug)]
struct CognitiveStoreLockCustody {
    _file: File,
    _path: PathBuf,
    #[cfg(windows)]
    _directory: File,
}

impl CognitiveStoreOpenGuard {
    fn open_lock_file(root: &Path) -> Result<CognitiveStoreLockCustody, CognitiveStoreError> {
        let path = root.join(COGNITIVE_STORE_LOCK_FILENAME);
        #[cfg(unix)]
        let file = {
            use std::os::unix::fs::OpenOptionsExt;
            OpenOptions::new()
                .read(true)
                .write(true)
                .create(true)
                .truncate(false)
                .mode(0o600)
                .custom_flags(libc::O_CLOEXEC | libc::O_NOFOLLOW)
                .open(&path)
                .map_err(unavailable)?
        };
        #[cfg(windows)]
        let (file, directory) = windows::open_lock_file(root, COGNITIVE_STORE_LOCK_FILENAME)?;
        #[cfg(not(any(unix, windows)))]
        let file = OpenOptions::new()
            .read(true)
            .write(true)
            .create(true)
            .truncate(false)
            .open(&path)
            .map_err(unavailable)?;

        #[cfg(unix)]
        {
            use std::os::unix::fs::MetadataExt;
            let metadata = file.metadata().map_err(unavailable)?;
            if !metadata.is_file() || metadata.nlink() != 1 || metadata.mode() & 0o7777 != 0o600 {
                return Err(CognitiveStoreError::Invalid(
                    "cognitive store lock must be one private regular file".to_string(),
                ));
            }
        }
        Ok(CognitiveStoreLockCustody {
            _file: file,
            _path: path,
            #[cfg(windows)]
            _directory: directory,
        })
    }

    pub(crate) fn acquire_shared(root: &Path) -> Result<Arc<Self>, CognitiveStoreError> {
        let guard = Self::open_lock_file(root)?;
        guard._file.try_lock_shared().map_err(|error| {
            CognitiveStoreError::Unavailable(format!(
                "cognitive store is fenced by recovery: {error}"
            ))
        })?;
        Ok(Arc::new(Self {
            custody: Arc::new(guard),
        }))
    }

    pub(crate) fn acquire_exclusive(root: &Path) -> Result<Self, CognitiveStoreError> {
        let guard = Self::open_lock_file(root)?;
        guard._file.try_lock().map_err(|error| {
            CognitiveStoreError::Unavailable(format!(
                "cognitive recovery cannot fence active store handles: {error}"
            ))
        })?;
        Ok(Self {
            custody: Arc::new(guard),
        })
    }
}

impl CognitiveStore {
    pub(crate) fn from_read_only_pool(
        pool: SqlitePool,
        owner_agent_id: AgentId,
        path: PathBuf,
    ) -> Self {
        Self {
            pool,
            commit_gate: CognitiveCommitGate::new(),
            owner_agent_id,
            path,
            _open_guard: None,
        }
    }

    /// Initialize or migrate the legacy store and verify its internal integrity.
    /// This entry point has no independent current-cut witness and cannot detect
    /// rollback to an internally valid old backup. Hosts requiring that guarantee
    /// must use `open_with_recovery` and never fall back here on recovery failure.
    pub async fn open(layout: &HeptaAgentLayout) -> Result<Self, CognitiveStoreError> {
        let root = create_private_directory(layout.cognitive_root())?;
        let open_guard = CognitiveStoreOpenGuard::acquire_shared(&root)?;
        let path = resolve_active_database_path(&root)?;
        #[cfg(windows)]
        windows::prepare_database(&root, &path)?;
        let sqlite_home = AbsolutePathBuf::try_from(root.to_path_buf())
            .map_err(|error| CognitiveStoreError::Invalid(error.to_string()))?;
        let commit_gate = CognitiveCommitGate::for_open_guard(&open_guard);
        let commit_check = commit_gate.clone();
        let pool = SqliteConfig::from_sqlite_home(sqlite_home)
            .open_commit_guarded_durable_evidence_pool(&path, move || commit_check.commit_allowed())
            .await
            .map_err(unavailable)?;
        MIGRATOR.run(&pool).await.map_err(classify_migrate_error)?;
        protect_database_file(&path)?;
        sqlx::query(
            "INSERT INTO cognitive_meta (singleton, schema_version, owner_agent_id)
             VALUES (1, ?, ?) ON CONFLICT(singleton) DO NOTHING",
        )
        .bind(i64::from(COGNITIVE_SCHEMA_VERSION))
        .bind(layout.agent_id().as_str())
        .execute(&pool)
        .await
        .map_err(unavailable)?;
        verify_store(&pool, layout.agent_id()).await?;
        Ok(Self {
            pool,
            commit_gate,
            owner_agent_id: layout.agent_id().clone(),
            path,
            _open_guard: Some(open_guard),
        })
    }

    /// On completion, close the shared SQLite pool before releasing this
    /// handle's store fence.
    ///
    /// Await this to completion before starting recovery. Cancelling this future
    /// is not a shutdown barrier. Successfully registered physical connections
    /// retain the original file and Windows directory custody through native
    /// Btree closure, including after a connection is detached from the pool.
    /// Other store handles and detached connections must also be closed/dropped
    /// before recovery can acquire the fence. State passes the original commit
    /// callback's custody into SQLx before native open, covering initialization
    /// cancellation as well. This lifetime guarantee does not authenticate Current.
    pub async fn close(self) {
        self.pool.close().await;
        drop(self);
    }

    pub fn path(&self) -> &Path {
        &self.path
    }

    pub fn owner_agent_id(&self) -> &AgentId {
        &self.owner_agent_id
    }

    /// Returns whether two handles refer to the same Agent-local database and
    /// owner.  This is crate-private so composite local writers can reject a
    /// lease/executor assembled from different stores before opening a
    /// transaction.  It is not an authority or capability check.
    pub(crate) fn is_same_local_store(&self, other: &Self) -> bool {
        self.owner_agent_id == other.owner_agent_id && self.path == other.path
    }

    pub async fn append_source(
        &self,
        access: &CognitiveAccess,
        draft: &SourceDraft,
    ) -> Result<SourceRevisionId, CognitiveStoreError> {
        let mut transaction = self
            .pool
            .begin_with("BEGIN IMMEDIATE")
            .await
            .map_err(unavailable)?;
        let source = self
            .append_source_tx(&mut transaction, access, draft)
            .await?;
        transaction.commit().await.map_err(unavailable)?;
        Ok(source)
    }

    pub(crate) async fn append_source_tx(
        &self,
        transaction: &mut Transaction<'_, Sqlite>,
        access: &CognitiveAccess,
        draft: &SourceDraft,
    ) -> Result<SourceRevisionId, CognitiveStoreError> {
        self.authorize(access, &draft.scope)?;
        validate_key(&draft.event_key, "source event key")?;
        if draft.content.is_empty() || draft.content.len() > MAX_SOURCE_BYTES {
            return Err(CognitiveStoreError::Invalid(format!(
                "source content must contain 1..={MAX_SOURCE_BYTES} bytes"
            )));
        }
        let source_id = SourceEventId::for_event(
            &self.owner_agent_id,
            &draft.scope,
            draft.kind,
            &draft.event_key,
        );
        let content_sha256 = Sha256Digest::for_bytes(&draft.content);
        let (scope_kind, workspace_sha256) = draft.scope.database_parts();
        let recorded_at = now_unix_seconds()?;
        let insert = sqlx::query(
            "INSERT INTO source_ledger (
                source_id, source_revision, owner_agent_id, scope_kind, workspace_sha256,
                source_kind, content, content_sha256, observed_at_unix_seconds,
                recorded_at_unix_seconds
             ) VALUES (?, 1, ?, ?, ?, ?, ?, ?, ?, ?)
             ON CONFLICT(source_id, source_revision) DO NOTHING",
        )
        .bind(source_id.as_str())
        .bind(self.owner_agent_id.as_str())
        .bind(scope_kind)
        .bind(workspace_sha256)
        .bind(draft.kind.as_str())
        .bind(&draft.content)
        .bind(content_sha256.as_str())
        .bind(draft.observed_at_unix_seconds)
        .bind(recorded_at)
        .execute(&mut **transaction)
        .await
        .map_err(unavailable)?;
        if insert.rows_affected() == 0 {
            let exact: i64 = sqlx::query_scalar(
                "SELECT COUNT(*) FROM source_ledger
                 WHERE source_id = ? AND source_revision = 1 AND owner_agent_id = ?
                   AND scope_kind = ? AND workspace_sha256 IS ? AND source_kind = ?
                   AND content = ? AND content_sha256 = ? AND observed_at_unix_seconds = ?",
            )
            .bind(source_id.as_str())
            .bind(self.owner_agent_id.as_str())
            .bind(scope_kind)
            .bind(workspace_sha256)
            .bind(draft.kind.as_str())
            .bind(&draft.content)
            .bind(content_sha256.as_str())
            .bind(draft.observed_at_unix_seconds)
            .fetch_one(&mut **transaction)
            .await
            .map_err(unavailable)?;
            if exact != 1 {
                return Err(CognitiveStoreError::Conflict(format!(
                    "source event {} was replayed with different content",
                    source_id.as_str()
                )));
            }
        }
        Ok(SourceRevisionId::new(source_id))
    }

    pub(crate) fn authorize(
        &self,
        access: &CognitiveAccess,
        scope: &CognitiveScope,
    ) -> Result<(), CognitiveStoreError> {
        if access.agent_id() != &self.owner_agent_id {
            return Err(CognitiveStoreError::AccessDenied(
                "cross-agent cognitive access requires an executable federation capability"
                    .to_string(),
            ));
        }
        if !scope.permits(access) {
            return Err(CognitiveStoreError::AccessDenied(
                "workspace-private cognitive record does not match the caller workspace"
                    .to_string(),
            ));
        }
        Ok(())
    }
}

pub(crate) fn validate_key(value: &str, label: &str) -> Result<(), CognitiveStoreError> {
    if value.trim().is_empty() || value.len() > 512 || value.as_bytes().contains(&0) {
        return Err(CognitiveStoreError::Invalid(format!(
            "{label} must contain 1..=512 non-NUL bytes"
        )));
    }
    Ok(())
}

pub(crate) fn decode_scope(
    row: &sqlx::sqlite::SqliteRow,
) -> Result<CognitiveScope, CognitiveStoreError> {
    CognitiveScope::parse(
        row.try_get("scope_kind").map_err(unavailable)?,
        row.try_get("workspace_sha256").map_err(unavailable)?,
    )
    .map_err(CognitiveStoreError::Corrupt)
}

